// ISO yyyy-MM-dd strings compare correctly as plain strings.
function dueNotBeforeIssued(group: AbstractControl): ValidationErrors | null {
  const { issuedDate, dueDate } = group.value as { issuedDate?: string; dueDate?: string };
  return issuedDate && dueDate && dueDate < issuedDate ? { dueBeforeIssued: true } : null;
}

// A project's invoices: lists them with their issue and due dates, shows what they add up to, adds a
// new draft, sends a draft, and marks a sent one as paid. Each invoice opens onto its line items.
@Component({
  selector: 'app-project-invoices',
  imports: [ReactiveFormsModule, CurrencyPipe, RouterLink],
  template: `
    <section aria-labelledby="project-invoices-heading" data-testid="project-invoices">
      <h2 id="project-invoices-heading">Invoices</h2>

      <form [formGroup]="form" (ngSubmit)="submit()" data-testid="invoice-form" novalidate>
        <div>
          <label for="invoice-amount">Amount (optional, or leave blank and add line items)</label>
          <input
            id="invoice-amount"
            type="number"
            inputmode="decimal"
            min="0.01"
            step="0.01"
            formControlName="amount"
            data-testid="invoice-form-amount"
            [attr.aria-invalid]="showError()"
            [attr.aria-describedby]="showError() ? 'invoice-amount-error' : null"
          />
          @if (showError()) {
            <p id="invoice-amount-error" role="alert" data-testid="invoice-form-amount-error">
              Enter an amount greater than zero with at most two decimal places, or leave it blank.
            </p>
          }
        </div>
        <div>
          <label for="invoice-issued">Issued (optional, defaults to today)</label>
          <input id="invoice-issued" type="date" formControlName="issuedDate" data-testid="invoice-form-issued" />
        </div>
        <div>
          <label for="invoice-due">Due (optional, defaults to 30 days after issue)</label>
          <input
            id="invoice-due"
            type="date"
            formControlName="dueDate"
            data-testid="invoice-form-due"
            [attr.aria-invalid]="showDueError()"
            [attr.aria-describedby]="showDueError() ? 'invoice-due-error' : null"
          />
          @if (showDueError()) {
            <p id="invoice-due-error" role="alert" data-testid="invoice-form-due-error">
              The due date cannot be before the issue date.
            </p>
          }
        </div>
        <button type="submit" data-testid="invoice-form-submit" [disabled]="saving()">
          Add invoice
        </button>
        @if (saveError()) {
          <p role="alert" data-testid="invoice-form-error">{{ saveError() }}</p>
        }
      </form>

      @if (invoices.error()) {
        <p role="alert" data-testid="project-invoices-error">Could not load the invoices.</p>
      } @else if (list().length === 0) {
        <p data-testid="project-invoices-empty">No invoices yet.</p>
      } @else {
        <table data-testid="project-invoices-table">
          <caption>Invoices for this project</caption>
          <thead>
            <tr>
              <th scope="col">Invoice</th>
              <th scope="col">Amount</th>
              <th scope="col">Status</th>
              <th scope="col">Issued</th>
              <th scope="col" [attr.aria-sort]="sortByDue() ? 'ascending' : null">
                <button
                  type="button"
                  data-testid="invoice-sort-due"
                  [attr.aria-pressed]="sortByDue()"
                  (click)="sortByDue.set(!sortByDue())"
                >
                  Due<span class="visually-hidden">, sort earliest first</span>
                </button>
              </th>
              <th scope="col"><span class="visually-hidden">Actions</span></th>
            </tr>
          </thead>
          <tbody>
            @for (i of rows(); track i.id) {
              <tr [attr.data-testid]="'invoice-row-' + i.id">
                <td data-testid="invoice-id">
                  <a
                    [routerLink]="['/projects', projectId(), 'invoices', i.id]"
                    [attr.data-testid]="'invoice-open-' + i.id"
                    [attr.aria-label]="'Open invoice #' + i.id"
                    >#{{ i.id }}</a
                  >
                </td>
                <td data-testid="invoice-amount">{{ i.amount | currency: 'USD' : 'symbol' : '1.2-2' : 'en-US' }}</td>
                <td data-testid="invoice-status">{{ i.status }}</td>
                <td data-testid="invoice-issued">{{ i.issuedDate }}</td>
                <td data-testid="invoice-due">{{ i.dueDate }}</td>
                <td>
                  @if (i.status === 'DRAFT') {
                    <button
                      type="button"
                      [attr.data-testid]="'invoice-send-' + i.id"
                      [attr.aria-label]="'Send invoice #' + i.id"
                      [disabled]="busy() === i.id"
                      (click)="send(i.id)"
                    >
                      Send
                    </button>
                  } @else if (i.status === 'SENT') {
                    <button
                      type="button"
                      [attr.data-testid]="'invoice-pay-' + i.id"
                      [attr.aria-label]="'Mark invoice #' + i.id + ' as paid'"
                      [disabled]="busy() === i.id"
                      (click)="pay(i.id)"
                    >
                      Mark paid
                    </button>
                  }
                </td>
              </tr>
            }
          </tbody>
          <tfoot>
            <tr>
              <th scope="row">Total</th>
              <td data-testid="project-invoices-total">{{ totalCents() / 100 | currency: 'USD' : 'symbol' : '1.2-2' : 'en-US' }}</td>
              <td colspan="4"></td>
            </tr>
          </tfoot>
        </table>
        @if (payError()) {
          <p role="alert" data-testid="invoice-pay-error">{{ payError() }}</p>
        }
        @if (sendError()) {
          <p role="alert" data-testid="invoice-send-error">{{ sendError() }}</p>
        }
      }
    </section>
  `,
})
export class ProjectInvoices {
  private readonly service = inject(InvoiceService);

  readonly projectId = input.required<number>();

  protected readonly invoices = rxResource({
    params: () => this.projectId(),
    stream: ({ params }) => this.service.listForProject(params),
  });
  protected readonly list = computed(() => (this.invoices.hasValue() ? this.invoices.value() : []));
  // Earliest due first when sorting by due date (ties by invoice number); otherwise invoice-number order.
  protected readonly sortByDue = signal(false);
  protected readonly rows = computed(() =>
    this.sortByDue()
      ? [...this.list()].sort((a, b) => a.dueDate.localeCompare(b.dueDate) || a.id - b.id)
      : this.list(),
  );
  // Sum in whole cents so the total is exact rather than accumulating floating-point error.
  protected readonly totalCents = computed(() =>
    this.list().reduce((sum, i) => sum + Math.round(i.amount * 100), 0),
  );

  protected readonly saving = signal(false);
  protected readonly saveError = signal<string | null>(null);

  // The invoice whose send or pay request is in flight.
  protected readonly busy = signal<number | null>(null);
  protected readonly sendError = signal<string | null>(null);
  protected readonly payError = signal<string | null>(null);

  protected readonly form = inject(NonNullableFormBuilder).group(
    {
      amount: ['', [Validators.min(0.01), Validators.pattern(/^\d+(\.\d{1,2})?$/)]],
      issuedDate: [''],
      dueDate: [''],
    },
    { validators: dueNotBeforeIssued },
  );

  protected showDueError(): boolean {
    return this.form.hasError('dueBeforeIssued') && this.form.controls.dueDate.dirty;
  }

  protected showError(): boolean {
    const control = this.form.controls.amount;
    return control.invalid && (control.touched || control.dirty);
  }

  protected submit(): void {
    if (this.form.invalid) {
      this.form.markAllAsTouched();
      return;
    }
    this.saving.set(true);
    this.saveError.set(null);
    const { amount, issuedDate, dueDate } = this.form.getRawValue();
    const invoice = {
      ...(amount !== '' && amount !== null ? { amount: Number(amount) } : {}),
      ...(issuedDate ? { issuedDate } : {}),
      ...(dueDate ? { dueDate } : {}),
    };
    this.service.create(this.projectId(), invoice).subscribe({
      next: (created) => {
        this.invoices.update((list) => [...(list ?? []), created]);
        this.form.reset();
        this.saving.set(false);
      },
      error: () => {
        this.saveError.set('Could not save the invoice. Please try again.');
        this.saving.set(false);
      },
    });
  }

  protected send(invoiceId: number): void {
    this.busy.set(invoiceId);
    this.sendError.set(null);
    this.service.send(this.projectId(), invoiceId).subscribe({
      next: (sent) => {
        this.replace(sent);
        this.busy.set(null);
      },
      error: () => {
        this.sendError.set('Could not send the invoice. Please try again.');
        this.busy.set(null);
      },
    });
  }

  protected pay(invoiceId: number): void {
    this.busy.set(invoiceId);
    this.payError.set(null);
    this.service.pay(this.projectId(), invoiceId).subscribe({
      next: (paid) => {
        this.replace(paid);
        this.busy.set(null);
      },
      error: () => {
        this.payError.set('Could not mark the invoice as paid. Please try again.');
        this.busy.set(null);
      },
    });
  }

  private replace(updated: Invoice): void {
    this.invoices.update((list) => (list ?? []).map((i) => (i.id === updated.id ? updated : i)));
  }
}
import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { Observable } from 'rxjs';

export const INVOICE_STATUSES = ['DRAFT', 'SENT', 'PAID'] as const;

export type InvoiceStatus = (typeof INVOICE_STATUSES)[number];

export interface Invoice {
  id: number;
  projectId: number;
  amount: number;
  status: InvoiceStatus;
  /** ISO date (yyyy-MM-dd) the invoice was issued. */
  issuedDate: string;
  /** ISO date (yyyy-MM-dd) payment is due. */
  dueDate: string;
}

/** An invoice as listed across all projects, with the name of the project it is for. */
export interface InvoiceSummary extends Invoice {
  projectName: string;
}

/** One thing an invoice charges for; its amount is quantity times unit price. */
export interface LineItem {
  id: number;
  description: string;
  qty: number;
  unitPrice: number;
  amount: number;
}

/** A single invoice with the line items it is built from. */
export interface InvoiceDetail extends Invoice {
  lineItems: LineItem[];
}

export interface NewLineItem {
  description: string;
  qty: number;
  unitPrice: number;
}

export interface NewInvoice {
  /** Raises the invoice as one figure; omit to start an empty draft built up from line items. */
  amount?: number;
  /** Defaults to today on the server when omitted. */
  issuedDate?: string;
  /** Defaults to 30 days after the issue date on the server when omitted. */
  dueDate?: string;
}

@Injectable({ providedIn: 'root' })
export class InvoiceService {
  private readonly http = inject(HttpClient);

  /** Every invoice across all projects, optionally narrowed to one status. */
  listAll(status?: InvoiceStatus): Observable<InvoiceSummary[]> {
    const params: Record<string, string> = status ? { status } : {};
    return this.http.get<InvoiceSummary[]>('/api/invoices', { params });
  }

  listForProject(projectId: number): Observable<Invoice[]> {
    return this.http.get<Invoice[]>(`/api/projects/${projectId}/invoices`);
  }

  create(projectId: number, invoice: NewInvoice): Observable<Invoice> {
    return this.http.post<Invoice>(`/api/projects/${projectId}/invoices`, invoice);
  }

  get(projectId: number, invoiceId: number): Observable<InvoiceDetail> {
    return this.http.get<InvoiceDetail>(`/api/projects/${projectId}/invoices/${invoiceId}`);
  }

  addLineItem(projectId: number, invoiceId: number, item: NewLineItem): Observable<InvoiceDetail> {
    return this.http.post<InvoiceDetail>(`/api/projects/${projectId}/invoices/${invoiceId}/line-items`, item);
  }

  updateLineItem(projectId: number, invoiceId: number, lineItemId: number, item: NewLineItem): Observable<InvoiceDetail> {
    return this.http.put<InvoiceDetail>(
      `/api/projects/${projectId}/invoices/${invoiceId}/line-items/${lineItemId}`,
      item,
    );
  }

  removeLineItem(projectId: number, invoiceId: number, lineItemId: number): Observable<InvoiceDetail> {
    return this.http.delete<InvoiceDetail>(`/api/projects/${projectId}/invoices/${invoiceId}/line-items/${lineItemId}`);
  }

  send(projectId: number, invoiceId: number): Observable<Invoice> {
    return this.http.post<Invoice>(`/api/projects/${projectId}/invoices/${invoiceId}/send`, null);
  }

  pay(projectId: number, invoiceId: number): Observable<Invoice> {
    return this.http.post<Invoice>(`/api/projects/${projectId}/invoices/${invoiceId}/pay`, null);
  }
}
package net.officefloor.hq.app.payment;

import java.math.BigDecimal;
import java.util.List;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;

public interface PaymentRepository extends JpaRepository<Payment, Long> {

    /** An invoice's payments, oldest first. */
    List<Payment> findByInvoiceIdOrderByDateAscIdAsc(Long invoiceId);

    /** Total paid against an invoice (zero when nothing has been paid). */
    @Query("SELECT COALESCE(SUM(p.amount), 0) FROM Payment p WHERE p.invoiceId = :invoiceId")
    BigDecimal sumAmountByInvoiceId(Long invoiceId);
}
-- Money a client has paid against an invoice: how much and on what day. An invoice can be paid in
-- several instalments; payments are financial records, so they block deleting their invoice.
CREATE TABLE payment (
    id         BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    invoice_id BIGINT         NOT NULL,
    amount     DECIMAL(12, 2) NOT NULL,
    paid_date  DATE           NOT NULL,
    CONSTRAINT payment_invoice_fk FOREIGN KEY (invoice_id) REFERENCES invoice (id),
    CONSTRAINT payment_amount_positive CHECK (amount > 0)
);

CREATE INDEX payment_invoice_idx ON payment (invoice_id, paid_date);

